  "source": "github",
  "current": [
    {
      "id": "angel-ai-end-to-end",
      "title": "PRIORITÉ ABSOLUE — Corriger et vérifier Angel AI OpenAI de bout en bout",
      "status": "running",
      "detail": "L’intelligence artificielle intégrée OpenAI ne fonctionne toujours pas. Cette correction passe avant toutes les autres demandes non critiques. Diagnostiquer le chemin complet interface → API/gateway → fournisseur OpenAI → réponse, corriger automatiquement ce qui est non sensible, obtenir une vraie réponse de test, puis conserver la tâche en tête tant que la correction n’est pas réellement validée et visible en production."
    },
    {
      "id": "recent-queue-cleanup",
      "title": "Nettoyer et fiabiliser la file GitHub visible",
      "status": "running",
      "detail": "Tri des demandes obsolètes, doublons et règles permanentes. La file visible doit désormais privilégier les modifications concrètes et récentes, avec requalification des éléments vieux de plus d’environ 1 h 30 au lieu de les laisser indéfiniment en pause."
    }
  ],
  "waiting": [
    {
      "id": "admin-auth-production-check",
      "title": "Vérifier le nouveau parcours d’accès administrateur",
      "status": "waiting_publish",
      "detail": "Contrôler en production : CAPTCHA visuel aléatoire multi-catégories, limitation des tentatives, écran noir de sécurité puis connexion, sans retour au PIN 2005 ni boucle."
    },
    {
      "id": "admin-news-production-check",
      "title": "Vérifier toutes les rubriques Actualités en production",
      "status": "waiting_publish",
      "detail": "Les correctifs sont sur main : chaque rubrique doit recevoir des contenus, « À la une » doit être plus fraîche et mieux personnalisée, sans recyclage excessif d’anciens articles."
    },
    {
      "id": "publication-production",
      "title": "Publier le dernier main en production",
      "status": "waiting_publish",
      "detail": "Le code est prêt sur main. Seule la synchronisation de la production reste à effectuer via le mécanisme officiel disponible. Ne pas présenter le code lui-même comme bloqué."
    },
    {
      "id": "admin-home-data",
      "title": "Finaliser les données utiles de l’accueil admin",
      "status": "waiting",
      "detail": "Regroupe les anciens points météo, agenda, mails, candidatures et bilan général qui étaient dispersés dans plusieurs tickets visibles."
    },
    {
      "id": "contact-cleanup",
      "title": "Finaliser la séparation formulaire Contact / discussion IA",
      "status": "waiting",
      "detail": "Regroupe les anciens tickets Contact redondants : formulaire sans chat ni texte moteur, fil IA séparé et vérification cache/session."
    },
    {
      "id": "cms-files-content",
      "title": "Finaliser fichiers et fonctions avancées du CMS",
      "status": "waiting",
      "detail": "Regroupe ajout de fichiers, édition/suppression d’articles, catégories multiples, images éditables et Sources/crédits."
    },
    {
      "id": "angel-os-presentation",
      "title": "Finaliser la présentation Angel OS",
      "status": "waiting",
      "detail": "Regroupe texte masqué, animations lisibles, ton officiel/tech et badge Propulsé par Angel OS."
    },
    {
      "id": "native-connections",
      "title": "Finaliser les connexions natives",
      "status": "waiting",
      "detail": "Regroupe migration APIs/OAuth, état réel des connexions, revue open source et crédits/licences."
    }
  ],
  "done": [
    {
      "id": "queue-main-state-fix",
      "title": "Séparer main prêt et publication en attente",
      "status": "done",
      "detail": "La file ne présente plus le dernier main comme bloqué lorsque seul le déploiement production reste en attente.",
      "commit": "57a6b172bb848dcb8123b138de15e9420b682484"
    },
    {
      "id": "admin-news-code-fix",
      "title": "Corriger la couverture et la personnalisation des actualités",
      "status": "done",
      "detail": "Couverture par rubrique, fraîcheur de À la une et recherche personnalisée renforcées sur main.",
      "commit": "25eabae87ab9d211b89dca777ca98c4a01282051"
    },
    {
      "id": "admin-auth-code-change",
      "title": "Remplacer le PIN actif par une vérification anti-bot visuelle",
      "status": "done",
      "detail": "Le nouveau flux a été implémenté sur main ; la validation finale en production reste séparée dans la file d’attente.",
      "commit": "96feeaacfe700d0bd0ecc2680ccc81d4c51003c3"
    },
    {
      "id": "admin-auth-monitor-merge",
      "title": "Intégrer le contrôle d’accès à la maintenance existante",
      "status": "done",
      "detail": "Le contrôle n’utilise plus une automatisation séparée ; il est intégré à Maintenance complète Angel OS."
    },
    {
      "id": "recent-backlog-consolidation",
      "title": "Ajouter les demandes récentes au backlog durable",
      "status": "done",
      "detail": "Accès admin, actualités, état main/publication, limite 1 h 30 et nettoyage de file ont été consolidés dans le backlog.",
      "commit": "f08d22e36e7f7568d630bb992b23002ae059d42a"
    }
  ]
}
